from Crypto.Util.number import long_to_bytes

# 1. 填入题目输出流
output_stream = ""
seq = [int(x) for x in output_stream]

# 2. 我们已经知道 Key 是 [8, 23, 114, 211, 360]
# 如果不想重新跑高斯消元，直接硬编码即可。
original_key = [8, 23, 114, 211, 360]
min_index = min(original_key) # 8

# 3. 构造降维后的 LFSR
# 新序列 u[t] = seq[t + min_index]
# 新 Key = old_key - min_index
reduced_key = [k - min_index for k in original_key]
# reduced_key = [0, 15, 106, 203, 352] -> 包含 0！可逆！

# 新 LFSR 的长度
reduced_length = 400 - min_index # 392

# 4. 提取状态并逆向
# 原始预热了 2024 次。输出流 seq[0] 是原始状态的第 2024 位。
# 对于 u 序列，u[t] 对应原始序列的 t+8。
# 我们拥有的 seq[0] 对应 u[2024 - 8] = u[2016]。
# 我们需要取 reduced_length (392) 位的状态。
# 当前状态是 u 序列在 t=2016 时的状态。
current_u_state = seq[:reduced_length]

print(f"Reduced LFSR Length: {reduced_length}")
print(f"Reduced Key: {reduced_key}")
print("正在逆向还原...")

# 我们需要逆推 2016 步，回到 u[0] (即 original[8])
steps_back = 2024 - min_index

for _ in range(steps_back):
    # 逆向逻辑：
    # forward: new = u[0] ^ sum(u[k] for k in key if k!=0)
    # reverse: u[0] = new ^ sum(...)
    # 在当前状态(是forward后的状态)里：
    # u[0] 变成了丢失的历史，u[1]...u[L-1] 变成了 state[0]...state[L-2]
    # new 变成了 state[L-1]
    
    last_bit_in = current_u_state[-1]
    
    feedback_sum = 0
    for k in reduced_key:
        if k != 0:
            # key k 对应的旧比特现在位于 k-1
            feedback_sum ^= current_u_state[k-1]
            
    recovered_bit_0 = last_bit_in ^ feedback_sum
    
    # 恢复状态
    current_u_state = [recovered_bit_0] + current_u_state[:-1]

# 5. 拼接 Flag
# current_u_state 现在是 u[0]...u[391]，对应原始 Flag 的 bit[8]...bit[399]
# 我们丢失了 bit[0]...bit[7]。
# 已知 Flag 开头是 'v'，即 0x76 = 01110110

missing_byte_val = ord('v')
missing_bits_str = bin(missing_byte_val)[2:].rjust(8, '0')
missing_bits = [int(b) for b in missing_bits_str]

final_bits = missing_bits + current_u_state

# 转 bytes
res_str = "".join(str(x) for x in final_bits)
res_int = int(res_str, 2)
flag = long_to_bytes(res_int)

print(f"\nFLAG: {flag.decode(errors='ignore')}")